import { db } from "@/lib/db";

export async function POST(request: Request) {
  const body = await request.json();
  const { title, airtimeMin } = body;

  // Check if the title is valid
  if (!title || typeof title !== "string" || title.trim() === "") {
    return new Response("Invalid title", { status: 400 });
  }

  // Check if the airtimeMin is valid
  if (!airtimeMin || typeof airtimeMin !== "number" || airtimeMin < 1 || airtimeMin > 360) {
    return new Response("Invalid airtimeMin", { status: 400 });
  }

  // Check if the Transmitter.id exists
  const transmitter = await db.transmitter.findUnique({
    where: { id: body.transmitterId },
  });
  if (!transmitter) {
    return new Response("Transmitter not found", { status: 404 });
  }

  // Create a new Broadcast record
  const broadcast = await db.broadcast.create({
    data: {
      title,
      airtimeMin,
      transmitter: {
        connect: { id: body.transmitterId },
      },
    },
  });

  // Return the created Broadcast record
  return new Response(JSON.stringify(broadcast), { status: 201 });
}

